def rearange_string(string):
    # Create a dictionary to store the count of each character
    char_count = {}
    for char in string:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Create a list to store the rearranged string
    rearranged_string = []

    # Iterate over the characters in the string
    for char in string:
        # If the character is already in the rearranged string, skip it
        if char in rearranged_string:
            continue

        # If the character is the last character in the string, add it to the rearranged string
        if char == string[-1]:
            rearranged_string.append(char)
            break

        # If the character is not the last character in the string, check if it can be added to the rearranged string
        if char_count[char] > 0:
            rearranged_string.append(char)
            char_count[char] -= 1

    # Return the rearranged string
    return ''.join(rearranged_string)

