    high = n - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == arr[mid - 1] and arr[mid] == arr[mid + 1]:
            return arr[mid]
        elif arr[mid] == arr[mid - 1]:
            high = mid - 1
        elif arr[mid] == arr[mid + 1]:
            low = mid + 1
        else:
            return arr[mid]

