def multiply_int(a, b):
    if a == 0 or b == 0:
        return 0
    if a == 1:
        return b
    if b == 1:
        return a
    if a == -1:
        return -b
    if b == -1:
        return -a
    if a > 0 and b > 0:
        return a + multiply_int(a, b-1)
    if a < 0 and b > 0:
        return -a + multiply_int(-a, b-1)
    if a > 0 and b < 0:
        return -a + multiply_int(-a, -b-1)
    if a < 0 and b < 0:
        return multiply_int(-a, -b)

