    r = n - 1
    while l <= r:
        mid = l + (r - l) // 2
        if arr[mid] == x:
            if mid == 0 or arr[mid - 1] < x:
                return mid
            else:
                r = mid - 1
        elif arr[mid] < x:
            l = mid + 1
        else:
            r = mid - 1
    return -1

