def find_longest_repeating_subseq(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]
    max_len = 0
    for i in range(n):
        dp[i][i] = 1
    for i in range(n-1):
        for j in range(i+1, n):
            if s[i] == s[j]:
                dp[i][j] = dp[i+1][j-1] + 2
            else:
                dp[i][j] = max(dp[i][j-1], dp[i+1][j])
            max_len = max(max_len, dp[i][j])
    return max_len

