def lps(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 1
    for i in range(n-1):
        j = i + 1
        dp[i][j] = 2 if s[i] == s[j] else 1
    for k in range(2, n):
        for i in range(n-k):
            j = i + k
            dp[i][j] = max(dp[i+1][j], dp[i][j-1], dp[i+1][j-1] + 2)
    return dp[0][n-1]

