def solve(arr, n):
    # Initialize inversion count
    inv_count = 0

    # Iterate over the array
    for i in range(n):
        for j in range(i + 1, n):
            # If the two elements are not equal
            if arr[i] != arr[j]:
                # Increment the inversion count
                inv_count += 1

    # Return true if the inversion count is even
    return inv_count % 2 == 0

