    for key, val in d.items():
        if val != value:
            return False
    return True

def find_peak(arr, n):
    start = 0
    end = n - 1
    while start < end:
        mid = start + (end - start) // 2
        if arr[mid] > arr[mid + 1]:
            end = mid
        else:
            start = mid + 1
    return arr[start]

def max_profit(prices, k):
    if k == 0 or len(prices) == 0:
        return 0
    if k == 1:
        return max(prices) - min(prices)
    if k > len(prices):
        return 0
    dp = [[0] * len(prices) for _ in range(k + 1)]
    for i in range(1, k + 1):
        max_diff = float('-inf')
        for j in range(1, len(prices)):
            max_diff = max(max_diff, dp[i - 1][j - 1] - prices[j - 1])
            dp[i][j] = max(dp[i][j - 1], prices[j] + max_diff)
    return dp[k][len(prices) - 1]

def add_pairwise(tuples):
    result = []
    for i in range(len(tuples)):
        for j in range(i+1, len(tuples)):
            result.append(tuples[i] + tuples[j])
    return result

def find_remainder(arr, n, m):
    result = 1
    for i in arr:
        result = (result * i) % m
    return result

def check_Consecutive(lst):
    for i in range(len(lst)-1):
        if lst[i+1] - lst[i] != 1:
            return False
    return True

def sort_counter(counter):
    sorted_counter = sorted(counter.items(), key=lambda x: x[1])
    return sorted_counter

def get_max_occuring_char(string):
    char_freq = {}
    for char in string:
        if char in char_freq:
            char_freq[char] += 1
        else:
            char_freq[char] = 1
    max_char = ""
    max_freq = 0
    for char in char_freq:
        if char_freq[char] > max_freq:
            max_freq = char_freq[char]
            max_char = char
    return max_char

def is_subset_sum(nums, target, sum):
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if nums[i] + nums[j] == sum:
                return True
    return False

import re

def match(string):
    pattern = re.compile(r'[A-Z][a-z]+')
    match = pattern.search(string)
    if match:
        return 'Yes'
    else:
        return 'No'

def first_Factorial_Divisible_Number(x):
    num = 1
    while True:
        if num % x == 0:
            return num
        num += 1

def remove_matching_tuple(tuple1, tuple2):
    result = []
    for item in tuple1:
        if item not in tuple2:
            result.append(item)
    return result

def largest_palindrome(arr, n):
    max_palindrome = 0
    for i in range(n):
        for j in range(i+1, n):
            if is_palindrome(arr[i], arr[j]):
                if arr[i] + arr[j] > max_palindrome:
                    max_palindrome = arr[i] + arr[j]
    return max_palindrome

def is_palindrome(num1, num2):
    return str(num1) == str(num1)[::-1] and str(num2) == str(num2)[::-1]

def binomial_probability(n, k, p):
    """
    Compute the binomial probability for the given number of trials, successes, and probability of success.
    """
    return math.comb(n, k) * (p**k) * ((1-p)**(n-k))

def frequency_Of_Largest(arr):
    max_val = max(arr)
    count = 0
    for i in arr:
        if i == max_val:
            count += 1
    return count

def extract_symmetric(lst):
    result = set()
    for i in range(len(lst)):
        for j in range(i+1, len(lst)):
            if lst[i] == lst[j][::-1]:
                result.add(tuple(lst[i]))
    return result

def binary_search(arr, x):
    l = 0
    r = len(arr) - 1
    while l <= r:
        mid = l + (r - l) // 2
        if arr[mid] == x:
            return True
        elif arr[mid] < x:
            l = mid + 1
        else:
            r = mid - 1
    return False

def binary_to_integer(binary_tuple):
    binary_str = ''.join(str(x) for x in binary_tuple)
    return int(binary_str, 2)

import re

def remove_lowercase(string):
    return re.sub(r'[a-z]', '', string)

import heapq

def heap_queue_smallest(nums, k):
    heap = []
    for num in nums:
        heapq.heappush(heap, num)
    smallest = []
    for _ in range(k):
        smallest.append(heapq.heappop(heap))
    return smallest

def gcd(a, b):
    if a == 0:
        return b
    return gcd(b % a, a)

def concatenate_elements(lst):
    result = ""
    for element in lst:
        result += element
    return result

def num_comm_div(a, b):
    # Find the smaller number
    smaller = min(a, b)
    # Find the common divisor
    for i in range(1, smaller + 1):
        if a % i == 0 and b % i == 0:
            return i
    return 1

def re_order(arr):
    non_zero = []
    for i in arr:
        if i != 0:
            non_zero.append(i)
    return non_zero + [0] * (len(arr) - len(non_zero))

def same_order(list1, list2):
    if len(list1) != len(list2):
        return False
    for i in range(len(list1)):
        if list1[i] != list2[i]:
            return False
    return True

def average_Odd(n):
    total = 0
    for i in range(1, n+1, 2):
        total += i
    return total / n

def no_of_subsequences(arr, k):
    count = 0
    for i in range(len(arr)):
        for j in range(i+1, len(arr)+1):
            product = 1
            for x in range(i, j):
                product *= arr[x]
            if product < k:
                count += 1
    return count
